import { test, expect } from "vitest";
import { createHmac } from "node:crypto";
import { verifyToken } from "/tmp/token-saver-runs/red-K1-jwt-deadline-4/src/auth/jwt.ts";
const b = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");
const sign = (h: object, p: object, s: string) => { const d = `${b(h)}.${b(p)}`; return `${d}.${createHmac("sha256", s).update(d).digest("base64url")}`; };
const now = Math.floor(Date.now() / 1000);
test("valid", () => expect(verifyToken(sign({alg:"HS256"}, {sub:"u1",exp:now+60}, "k"), "k")).toEqual({sub:"u1",exp:now+60}));
test("expired", () => expect(() => verifyToken(sign({alg:"HS256"}, {sub:"u1",exp:now-1}, "k"), "k")).toThrow("expired"));
test("wrong secret", () => expect(() => verifyToken(sign({alg:"HS256"}, {sub:"u1",exp:now+60}, "x"), "k")).toThrow("signature"));
test("alg none", () => expect(() => verifyToken(`${b({alg:"none"})}.${b({sub:"u1",exp:now+60})}.`, "k")).toThrow("alg"));
test("tampered payload", () => { const [h,,s] = sign({alg:"HS256"}, {sub:"u1",exp:now+60}, "k").split("."); expect(() => verifyToken(`${h}.${b({sub:"admin",exp:now+60})}.${s}`, "k")).toThrow("signature"); });
EOF
npx vitest run --root / /tmp/jwt-smoke.test.ts 2>&1 | tail -8; npx tsc --noEmit -p . 2>&1 | tail -5; rm /tmp/jwt-smoke.test.ts

